from boltons.iterutils import split, split_iter, research, default_enter

for factory in (lambda: [1, None, 2], lambda: (1, None, 2), lambda: iter([1, None, 2]), lambda: 'abc', lambda: {'a': 1, 'b': 2}, lambda: []):
    for func in (split, lambda *a, **kw: list(split_iter(*a, **kw))):
        src = factory()
        expected = list(factory())
        result = func(src, maxsplit=0)
        assert result == [expected], (src, result)
        assert result[0] is not src

shared = {'value': 42}
root = {'a': shared, 'b': shared}
query = lambda p, k, v: k == 'value'
assert research(root, query) == [(('a', 'value'), 42)]
assert research(root, query, cache=False) == [(('a', 'value'), 42), (('b', 'value'), 42)]
assert research(root, query, False, default_enter, False) == research(root, query, cache=False)
for root in ([], {}):
    if isinstance(root, list):
        root.append(root)
    else:
        root['self'] = root
    assert research(root, cache=True)
    try:
        research(root, cache=False)
    except RecursionError:
        pass
    else:
        raise AssertionError('expected circular reference detection')
print('Targeted edge-case checks passed')
